css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .82); position: relative; }
.loader .ball { position: absolute; left: 4%; top: 18%; width: 48%; height: calc(var(--loader-size) * .48); border-radius: 50%; background: repeating-linear-gradient(42deg, transparent 0 calc(var(--loader-size) * .05), color-mix(in srgb, #000 22%, var(--accent)) calc(var(--loader-size) * .05) calc(var(--loader-size) * .062)), repeating-linear-gradient(-42deg, transparent 0 calc(var(--loader-size) * .05), color-mix(in srgb, #fff 26%, var(--accent)) calc(var(--loader-size) * .05) calc(var(--loader-size) * .062)), var(--accent); box-shadow: inset calc(var(--loader-size) * -.05) calc(var(--loader-size) * -.05) calc(var(--loader-size) * .1) rgba(15, 23, 42, .32); animation: yarn-spin calc(var(--loader-speed) * 2) linear infinite; }
.loader span { position: absolute; left: 48%; top: 38%; height: 34%; border: calc(var(--loader-size) * .035) solid var(--accent-2); border-left: 0; border-top: 0; border-radius: 0 0 70% 0; animation: unwind calc(var(--loader-speed) * 2.4) ease-in-out infinite; }
@keyframes yarn-spin { to { transform: rotate(360deg); } }
@keyframes unwind { 0% { opacity: 0; width: 5%; } 14% { opacity: 1; } 78% { opacity: 1; width: 48%; } 100% { opacity: 0; width: 48%; } }
